begin;

-- Reconcile National Assembly MPs to the Parliament list of members
-- (alphabetical, as on 18 February 2026, sha256 7b67455edd7b95ade88110354b8a28d16bf1f29687c0dfe0ae48c6c3228d53d7).
--
-- 1. Rows matched to a member on the list are renamed to the list's canonical
--    name ("Surname, Mr. Given Names") and given the list's party. Rows that
--    matched only loosely (spelling, middle name, double-barrelled surname,
--    party-less) are listed in the log with the old name so they can be reviewed.
-- 2. Members on the list with no row are inserted.
-- 3. Initials-only rows with no linked records are deprecated (removed, logged).
-- 4. Rows not on the list but with linked disclosures, spending or judicial
--    records are kept: they are likely former members, and their records must
--    not be lost.
--
-- Every change is written to public.mp_merge_log.

alter table public.mp_merge_log drop constraint if exists mp_merge_log_action_check;
alter table public.mp_merge_log add constraint mp_merge_log_action_check
  check (action in ('merged', 'deprecated', 'renamed', 'inserted'));

-- 1. Rename matched rows
